"""Builds docs/brand/v3/logo-sheet.html (self-contained) from the v3 SVGs. Run build_logo.py first."""
import os
H = os.path.dirname(__file__)
def svg(n, st=""): return open(os.path.join(H, "svg", n)).read().replace("<svg ", f'<svg style="{st}" ', 1)
def tile(bg, inner, cap, border="#D8E2DC"): return f'<figure style="margin:0"><div class="t" style="background:{bg};border-color:{border}">{inner}</div><figcaption>{cap}</figcaption></figure>'
CSS = """body{margin:0;font-family:Manrope,Inter,system-ui,sans-serif;color:#16302B;background:#fff;line-height:1.55}.w{max-width:1040px;margin:0 auto;padding:0 20px}
header{background:#014A43;color:#fff;padding:44px 0}header h1{margin:0 0 6px;font-size:32px}header p{margin:4px 0;color:#CFE3DB;max-width:700px}h2{margin:44px 0 8px;font-size:22px}p.n{color:#4B6660;margin:0 0 14px;max-width:760px}
.g{display:grid;gap:14px}.g2{grid-template-columns:1fr 1fr}.g3{grid-template-columns:repeat(3,1fr)}.t{border:1px solid;border-radius:20px;min-height:160px;display:flex;align-items:center;justify-content:center;padding:28px}figcaption{font-size:12px;color:#4B6660;margin-top:6px}
table{border-collapse:collapse;width:100%;font-size:14px}td,th{border-bottom:1px solid #D8E2DC;padding:8px 10px;text-align:left}.sw{display:flex;gap:10px;flex-wrap:wrap}.sw div{width:150px}.sw i{display:block;height:64px;border-radius:12px;border:1px solid #D8E2DC;margin-bottom:6px}.sw span{font-size:12.5px}
@media(max-width:760px){.g2,.g3{grid-template-columns:1fr}}"""
SW = lambda c, n, r: f'<div><i style="background:{c}"></i><b>{c}</b><br><span>{n}. {r}</span></div>'
html = f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>AAICBI logo sheet</title><style>{CSS}</style></head><body>
<header><div class="w"><h1>AAICBI logo, version 3</h1><p>The Nested Ascent mark in the platform&rsquo;s own colours. The mark stands on the word, and together they fill one equilateral triangle.</p></div></header>
<div class="w">
<h2>Tier 1 · Everyday logo</h2><p class="n">The mark above the word, no descriptor. Every side of the triangle is the same length: the base is the word&rsquo;s baseline, and the two sides run along the mark&rsquo;s outer legs. No part of any letter crosses a side (the nearest point, the top corner of the last I, clears it by 0.6 of a unit on a 193-unit-tall logo).</p>
<div class="g g2">{tile("#F7F5F0", svg("aaicbi-logo.svg","width:300px"), "Light")}{tile("#14181A", svg("aaicbi-logo-dark.svg","width:300px"), "Dark (the platform&rsquo;s dark theme)", "#14181A")}</div>
<h2>Tier 2 · Formal lockup</h2><p class="n">The same logo with &ldquo;Africa&rsquo;s AI Capacity Building Initiative&rdquo; beneath the base, for letterheads, certificates and investor decks. It is not used in everyday places.</p>
<div class="g g2">{tile("#F7F5F0", svg("aaicbi-formal.svg","width:260px"), "Light")}{tile("#14181A", svg("aaicbi-formal-dark.svg","width:260px"), "Dark", "#14181A")}</div>
<h2>Compact versions</h2><p class="n">Below about 120 px tall the letters in the triangle become too small to read. Headers and bars use the compact lockup, with the word beside the mark; the symbol alone is for icons and avatars.</p>
<div class="g g3">{tile("#F7F5F0", svg("aaicbi-logo-compact.svg","width:220px"), "Compact, light")}{tile("#14181A", svg("aaicbi-logo-compact-dark.svg","width:220px"), "Compact, dark", "#14181A")}{tile("#F7F5F0", svg("aaicbi-formal-compact.svg","width:300px"), "Compact formal (name beside)")}</div>
<div class="g g3" style="margin-top:14px">{tile("#F7F5F0", svg("aaicbi-symbol.svg","width:72px")+svg("aaicbi-symbol.svg","width:32px")+svg("aaicbi-symbol.svg","width:16px"), "Symbol, 72 / 32 / 16 px")}{tile("#E4EEE7", svg("aaicbi-app-icon.svg","width:84px;border-radius:19px")+svg("aaicbi-app-icon-dark.svg","width:84px;border-radius:19px"), "App icons")}{tile("#E4EEE7", svg("aaicbi-logo-mono.svg","width:120px")+'<span style="background:#016B61;padding:12px;display:inline-block;margin-left:14px">'+svg("aaicbi-logo-mono-white.svg","width:100px")+'</span>', "One colour: Midnight-teal and white")}</div>
<h2>Colour (platform tokens)</h2><div class="sw">{SW("#014A43","Teal deep","big chevron and word, light")}{SW("#85C79A","Green","second chevron, light")}{SW("#D99A34","Gold","the node")}{SW("#E8F0ED","Ink (dark theme)","big chevron and word, dark")}{SW("#4FBBA8","Teal (dark theme)","second chevron, dark")}{SW("#E3AC55","Gold (dark theme)","the node, dark")}</div>
<p class="n" style="margin-top:12px">The green second chevron has a low contrast on white and sand (about 1.9 : 1). It is a large shape beside the dark chevron, but it fades at 16 px; at that size the mark still reads as an A with a node.</p>
<h2>Rules</h2><table><tr><th>Rule</th><th>Value</th></tr><tr><td>Clear space</td><td>One quarter of the logo&rsquo;s height on every side</td></tr><tr><td>Minimum size, triangle logo</td><td>120 px tall (30 mm) with the word readable; smaller, use the compact logo</td></tr><tr><td>Minimum size, compact logo</td><td>100 px wide (25 mm)</td></tr><tr><td>Minimum size, symbol</td><td>16 px (5 mm)</td></tr><tr><td>Never</td><td>Stretch, rotate, recolour, add shadows or outlines, rearrange the parts, or place on busy images</td></tr></table>
<h2>The name</h2><p class="n">AAICBI is pronounced &ldquo;Ayak-bi&rdquo;, close to the Turkish <i>ayakkabı</i> (shoe): what a person wears to protect their feet when they set out on a journey. The platform is built for that journey of self-development. The story belongs on the about page, not on the logo.</p>
</div></body></html>'''
open(os.path.join(H, "logo-sheet.html"), "w").write(html)
